BEGIN
    DECLARE max_rows INT;
    DECLARE i INT;
    DECLARE sql_text TEXT DEFAULT '';

    -- Определяем максимальное количество записей у студента
    SELECT MAX(cnt) INTO max_rows
    FROM (
        SELECT id, COUNT(*) AS cnt
        FROM exams
        WHERE date >='2025-09-01' AND date <= '2025-10-31' ORDER BY date DESC
    ) AS counts;

    -- Формируем динамический запрос
    SET sql_text = 'SELECT s.id AS student_id, s.group_id, s.full_name AS student_name, ';

    SET i = 1;
    WHILE i <= max_rows DO
        SET sql_text = CONCAT(sql_text, 'MAX(CASE WHEN es.row_num = ', i, ' THEN es.points ELSE NULL END) AS `', i, '`, ');
        SET i = i + 1;
    END WHILE;

    -- Убираем последнюю запятую
    SET sql_text = LEFT(sql_text, LENGTH(sql_text) - 2);

    SET sql_text = CONCAT(sql_text, '
    FROM students s
    LEFT JOIN (
        SELECT
            student_id,
            points,
            IF(@prev_student = student_id, @row_num := @row_num + 1, @row_num := 1) AS row_num,
            @prev_student := student_id
        FROM exam_sessions, (SELECT @row_num := 0, @prev_student := NULL) AS init
        ORDER BY student_id
    ) es ON s.id = es.student_id
    GROUP BY s.id, s.group_id, s.full_name
    ORDER BY s.full_name;');

    -- Выполняем сгенерированный запрос
    SET @sql = sql_text;
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END

