BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE hw_name VARCHAR(255);
    DECLARE hw_id INT;
    DECLARE sql_text TEXT DEFAULT '';
    DECLARE cur CURSOR FOR
        SELECT DISTINCT h.id, h.name
        FROM homework h
        WHERE h.deadline >= '2025-10-05' AND h.deadline <= '2025-10-31'
        ORDER BY h.type, h.deadline DESC;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- Начинаем формировать динамический запрос
    SET sql_text = 'SELECT s.id AS student_id, s.group_id, s.full_name AS student_name, p.full_name AS proctor_name ';

    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO hw_id, hw_name;
        IF done THEN
            LEAVE read_loop;
        END IF;
        -- Экранируем название задания
        SET hw_name = REPLACE(hw_name, '`', '``');
        -- Добавляем столбец с названием задания
        SET sql_text = CONCAT(sql_text, ', MAX(CASE WHEN h.id = ', hw_id, ' THEN hs.result ELSE NULL END) AS `', hw_name, '`');
    END LOOP;
    CLOSE cur;

    -- Добавляем остальную часть запроса
    SET sql_text = CONCAT(sql_text, ' FROM students s
        LEFT JOIN proctors p ON s.group_id = p.group_id
        LEFT JOIN homework_sessions hs ON s.id = hs.student_id
        LEFT JOIN homework h ON hs.homework_id = h.id
        GROUP BY s.id, s.group_id, s.full_name, p.full_name
        ORDER BY s.full_name;');

    -- Выполняем сгенерированный запрос
    SET @sql = sql_text;
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END

